/*
  Regression test for the missing navigation bar.
  The root layout (src/routes/__root.tsx) should render a <Nav /> component
  that exposes a DOM element with data-testid="site-nav". Before the fix the
  element does not exist, causing the test to fail. After adding the <Nav />
  render the test passes.
*/

import { render, screen } from "@testing-library/react";
import { expect, test } from "vitest";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { createRouter } from "@tanstack/react-router";

// Import the root route definition (the object created by createRootRouteWithContext)
import { Route as rootRoute } from "../src/routes/__root";

// Helper: build a router instance that uses the existing route tree.
// This mirrors the production setup without needing the full app entry point.
const router = createRouter({
  routeTree: rootRoute,
  defaultPreload: "intent",
});

// A tiny wrapper that provides the router context required by the root route.
function RouterProviderWrapper({ children }: { children: React.ReactNode }) {
  return <router.Provider>{children}</router.Provider>;
}

// ---------------------------------------------------------------------------
// Test
// ---------------------------------------------------------------------------
test("navigation bar is rendered in the root layout", async () => {
  // The root route expects a QueryClient in its context. Provide one here.
  const queryClient = new QueryClient();

  render(
    <RouterProviderWrapper>
      {/* The component exported by the root route renders the whole app layout. */}
      <rootRoute.Component />
    </RouterProviderWrapper>
  );

  // The Nav component (once correctly imported) should render an element with
  // data-testid="site-nav" (this selector can be adjusted to match the actual
  // Nav implementation, e.g., role="navigation").
  const nav = await screen.findByTestId("site-nav");

  expect(nav).toBeInTheDocument();
});

