// regression.test.ts
// This test reproduces the routing bug in `app/projects/[slug]/page.tsx`.
// It initially **fails** because the component is a client component that
// receives no `params` prop, resulting in the "Project not found" fallback.
// After fixing the component (e.g., removing `'use client'` or using
// `useParams`), the test will **pass**.

import React from "react";
import { render, screen } from "@testing-library/react";
import ProjectDetail from "@/app/projects/[slug]/page";

// Mock framer‑motion to avoid animation‑related errors in the test environment.
jest.mock("framer-motion", () => ({
  motion: {
    div: (props: any) => <div {...props} />,
    span: (props: any) => <span {...props} />,
    h1: (props: any) => <h1 {...props} />,
    p: (props: any) => <p {...props} />,
    section: (props: any) => <section {...props} />,
  },
}));

describe("ProjectDetail page routing", () => {
  it("renders the correct project when a valid slug is supplied", () => {
    // Render the page component with the dynamic route parameter.
    render(<ProjectDetail params={{ slug: "rolewiz" }} />);

    // The page should display the project title (an <h1> element).
    const title = screen.getByRole("heading", { name: /rolewiz/i });
    expect(title).toBeInTheDocument();
  });
});
